nextflow_process {

    name "Test Process SOURMASH_TAXANNOTATE"
    script "../main.nf"
    process "SOURMASH_TAXANNOTATE"
    config "./nextflow.config"

    tag "modules"
    tag "modules_nfcore"
    tag "sourmash"
    tag "sourmash/taxannotate"
    tag "sourmash/gather"
    tag "sourmash/sketch"

    setup {
        run("SOURMASH_SKETCH", alias: "SOURMASH_SKETCH_1") {
            script "../../sketch/main.nf"
            config "./nextflow.config"
            process {
            """
            input[0] = Channel.fromList(
                [
                    [
                        [ id: 'test1' ],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                    ]
                ]
            )
            input[1] =  false // false means do _not_ merge sigs
            """
            }
        }

        run("SOURMASH_SKETCH", alias: "SOURMASH_SKETCH_2") {
            script "../../sketch/main.nf"
            config "./nextflow.config"
            process {
            """
            input[0] = Channel.fromList(
                [
                    [
                        [ id: 'db' ],
                        file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/genome.fasta', checkIfExists: true)
                    ]
                ]
            )
            input[1] =  false // false means do _not_ merge sigs
            """
            }
        }

        run("SOURMASH_GATHER") {
            script "../../gather/main.nf"
            process {
            """
            input[0] = SOURMASH_SKETCH_1.out.signatures
            input[1] = SOURMASH_SKETCH_2.out.signatures.map{it[1]}
            input[2] = false // save_unassigned
            input[3] = false // save_matches_sig
            input[4] = false // save_prefetch
            input[5] = false // save_prefetch_csv
            """
            }
        }
    }

    test("sarscov2 genome - fasta") {

        when {
            process {
                """
                input[0] = SOURMASH_GATHER.out.result
                input[1] = Channel.of(
                        'ident,superkingdom,phylum,class,order,family,genus,species',
                        'db,d__Riboviria,p__Pisuviricota,c__Pisoniviricetes,o__Nidovirales,f__Coronaviridae,g__Betacoronavirus,s__SARS‑CoV‑2'
                    )
                    .collectFile { item ->
                        [ "taxonomy.csv", item + '\\n' ]
                    }
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("sarscov2 genome - fasta - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = SOURMASH_GATHER.out.result
                input[1] = Channel.of(
                        'ident,superkingdom,phylum,class,order,family,genus,species',
                        'db,d__Riboviria,p__Pisuviricota,c__Pisoniviricetes,o__Nidovirales,f__Coronaviridae,g__Betacoronavirus,s__SARS‑CoV‑2'
                    )
                    .collectFile { item ->
                        [ "taxonomy.csv", item + '\\n' ]
                    }
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

}

process {
    withName: 'SOURMASH_SKETCH_1|SOURMASH_SKETCH_2' {
        ext.args = "dna --name db"
    }
    withName: SOURMASH_GATHER {
        ext.args = "--threshold-bp 10 --ksize 31"
    }
}
